"""Only compare tiny public examples; this is not the acceptance checker."""
import math
def compare(actual,expected,field=None):
    if type(expected) is int:
        if type(actual) is not int or actual!=expected:raise ValueError('public discrete value differs')
    elif type(expected) is float:
        if type(actual) not in (float,int) or not math.isfinite(actual):
            raise ValueError('expected finite number')
        if not -1e9<=actual<=1e9 or (expected>=0 and actual<0):
            raise ValueError('public example number outside range/sign')
        if expected==0 and field in ('flow','edge_load') and actual!=0:
            raise ValueError('public withdrawn amount/load must be exactly zero')
        if field!='edge_load' and abs(actual-expected)>1e-7+1e-7*max(abs(actual),abs(expected)):
            raise ValueError('public example number differs')
    elif type(expected) is dict:
        if type(actual) is not dict or set(actual)!=set(expected):raise ValueError('public example keys differ')
        for k in expected:compare(actual[k],expected[k],k)
    elif type(expected) is list:
        if type(actual) is not list or len(actual)!=len(expected):raise ValueError('public example dimensions differ')
        for a,b in zip(actual,expected):compare(a,b,field)
    elif type(actual) is not type(expected) or actual!=expected:raise ValueError('public example value differs')

def public_load_relation(response):
    # Only the canned one-edge, one-commodity proposal, not a full objective.
    for case in response.get('cases',[]):
        for event in case['events']:
            if event['op']=='issue' and event['result']['status']=='optimal':
                result=event['result'];amount=result['flow'][0][0];load=result['edge_load'][0]
                if abs(amount-load)>1e-7+1e-7*max(abs(amount),abs(load)):
                    raise ValueError('public edge load differs from amount')
"""Bounded ordinary-user subprocess for PUBLIC sanity checks, not private grading.

The enclosing container/workspace supplies filesystem isolation. The child helper
adds the published rlimits and seccomp policy without root, chroot or UID leases.
"""
from dataclasses import dataclass
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import time


class InfrastructureError(RuntimeError):
    pass


class CandidateFailure(RuntimeError):
    pass


@dataclass
class Result:
    stdout: bytes
    stderr: bytes
    returncode: int
    seconds: float


def storage_over_budget(root):
    total=0
    entries=0
    stack=[Path(root)]
    while stack:
        path=stack.pop()
        try:
            st=path.lstat()
            entries+=1
            if stat.S_ISREG(st.st_mode):
                total+=max(st.st_size,st.st_blocks*512)
            elif stat.S_ISDIR(st.st_mode):
                with os.scandir(path) as it:
                    for entry in it:
                        stack.append(Path(entry.path))
                        if entries+len(stack)>4096:
                            return True
        except FileNotFoundError:
            continue
        if total>64*1024*1024 or entries>4096:
            return True
    return False


def invoke(worker,argv,data,scratch,*,timeout=180,stdout_limit=8*1024*1024,stderr_limit=256*1024,pythonpath=None):
    """Run a single non-forking child with bounded real stdin/stdout/stderr pipes."""
    if os.getuid()==0 or os.geteuid()==0:
        raise InfrastructureError('public check must run as an ordinary nonroot user')
    if not isinstance(data,bytes) or len(data)>8*1024*1024:
        raise InfrastructureError('public fixture input exceeds byte bound')
    if not 0<timeout<=180 or stdout_limit<0 or stderr_limit<0:
        raise InfrastructureError('invalid public capture budget')
    worker=Path(worker).resolve()
    if not worker.is_file() or not os.access(worker,os.X_OK) or worker.stat().st_mode&0o6000:
        raise InfrastructureError('missing or unsafe public check_worker executable')
    scratch=Path(scratch).resolve()
    scratch.mkdir(mode=0o700)
    env={'PATH':'/usr/local/bin:/usr/bin:/bin','HOME':str(scratch.parent),
         'LANG':'C','LC_ALL':'C','TMPDIR':str(scratch),
         'PYTHONUNBUFFERED':'1','PYTHONDONTWRITEBYTECODE':'1','PYTHONHASHSEED':'0',
         'OPENBLAS_NUM_THREADS':'1','OMP_NUM_THREADS':'1','MKL_NUM_THREADS':'1'}
    if pythonpath is not None:
        env['PYTHONPATH']=str(pythonpath)
        env['LD_LIBRARY_PATH']=str(Path(pythonpath).parent/'native')
    start=time.monotonic()
    deadline=start+timeout
    next_storage=start
    process=None
    streams=[]
    selector=selectors.DefaultSelector()
    output=[bytearray(),bytearray()]
    offset=0
    try:
        # Protect the launch/handle assignment against an interruption. The C
        # helper restores the child's signal mask before applying its policy.
        old_mask=signal.pthread_sigmask(signal.SIG_BLOCK,{signal.SIGTERM,signal.SIGINT})
        try:
            process=subprocess.Popen([str(worker),*argv],stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                                     cwd=scratch.parent,env=env,close_fds=True)
            streams=[process.stdin,process.stdout,process.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK,old_mask)
        for stream in streams:
            os.set_blocking(stream.fileno(),False)
        if data:
            selector.register(process.stdin,selectors.EVENT_WRITE,-1)
        else:
            process.stdin.close()
        selector.register(process.stdout,selectors.EVENT_READ,0)
        selector.register(process.stderr,selectors.EVENT_READ,1)
        while selector.get_map() or process.poll() is None:
            now=time.monotonic()
            if now>=deadline:
                raise CandidateFailure('candidate wall deadline exceeded')
            if now>=next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('sampled writable storage emergency budget exceeded')
                next_storage=now+.25
            for key,_ in selector.select(min(.1,deadline-now)):
                stream,index=key.fileobj,key.data
                if index==-1:
                    try:
                        sent=os.write(stream.fileno(),memoryview(data)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        selector.unregister(stream);stream.close();continue
                    offset+=sent
                    if offset==len(data):
                        selector.unregister(stream);stream.close()
                else:
                    limit=(stdout_limit,stderr_limit)[index]
                    try:
                        block=os.read(stream.fileno(),min(65536,limit-len(output[index])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        selector.unregister(stream);stream.close()
                    elif len(output[index])+len(block)>limit:
                        raise CandidateFailure(('stdout','stderr')[index]+' byte limit exceeded')
                    else:
                        output[index].extend(block)
        # Streams may close before the child exits; EOF alone is not success.
        try:
            code=process.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired as exc:
            raise CandidateFailure('candidate wall deadline exceeded') from exc
        if storage_over_budget(scratch):
            raise InfrastructureError('sampled writable storage emergency budget exceeded')
        return Result(bytes(output[0]),bytes(output[1]),code,time.monotonic()-start)
    finally:
        try:
            if process is not None:
                if process.poll() is None:
                    process.kill()
                process.wait(timeout=5)
        except BaseException as exc:
            raise InfrastructureError('public child cleanup failed') from exc
        finally:
            selector.close()
            for stream in streams:
                stream.close()
"""Whole-request validation only; no numerical or replay engine."""
import json
class InvalidRequest(ValueError): pass
def bad(): raise InvalidRequest('invalid_request')
def loads(raw):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d:bad()
            d[k]=v
        return d
    def constant(_):bad()
    try:
        if isinstance(raw,bytes):raw=raw.decode('utf-8')
        return json.loads(raw,object_pairs_hook=pairs,parse_constant=constant)
    except (ValueError,UnicodeError,RecursionError):bad()
def keys(x,names):
    if type(x) is not dict or set(x)!=set(names.split()):bad()
def integer(x,lo,hi):
    if type(x) is not int or not lo<=x<=hi:bad()
def sequence(x,lo,hi):
    if type(x) is not list or not lo<=len(x)<=hi:bad()
def path_ok(path,source,sink,edges):
    if path is None:return
    sequence(path,1,12);current=source;seen={source}
    for e in path:
        integer(e,0,len(edges)-1);u,v,_=edges[e]
        if u!=current or v in seen:bad()
        seen.add(v);current=v
    if current!=sink:bad()
def distinct(paths):
    values=[tuple(p) for p in paths if p is not None]
    if len(values)!=len(set(values)):bad()
def mode(x):
    if type(x) is not str or x not in ('route','admit'):bad()
def validate(v):
    keys(v,'cases');sequence(v['cases'],0,6);events_total=issues_total=0
    for case in v['cases']:
        keys(case,'nodes edges commodities workers quorum max_lag relax rho mode events')
        n=case['nodes'];integer(n,2,32)
        edges=case['edges'];sequence(edges,1,64);pairs=set()
        for edge in edges:
            sequence(edge,3,3);u,w,c=edge
            integer(u,0,n-1);integer(w,0,n-1);integer(c,0,1000)
            if u==w or (u,w) in pairs:bad()
            pairs.add((u,w))
        coms=case['commodities'];sequence(coms,0,24);slots=[]
        for com in coms:
            keys(com,'source sink demand paths');s,t=com['source'],com['sink']
            integer(s,0,n-1);integer(t,0,n-1)
            if s==t:bad()
            integer(com['demand'],0,1000);sequence(com['paths'],0,8)
            for p in com['paths']:path_ok(p,s,t,edges)
            distinct(com['paths']);slots.append(list(com['paths']))
        if sum(map(len,slots))>96:bad()
        workers=case['workers'];sequence(workers,1,8);ownership=[]
        for ids in workers:
            sequence(ids,0,len(coms))
            for k in ids:integer(k,0,len(coms)-1)
            if ids!=sorted(set(ids)):bad()
            ownership.extend(ids)
        if sorted(ownership)!=list(range(len(coms))):bad()
        integer(case['quorum'],1,len(workers));integer(case['max_lag'],0,12)
        sequence(case['relax'],2,2);a,b=case['relax']
        integer(a,1,16);integer(b,1,16)
        if not b<=a<2*b:bad()
        integer(case['rho'],1,8);mode(case['mode'])
        sequence(case['events'],1,256);events_total+=len(case['events'])
        tickets=set();saves={}
        for ev in case['events']:
            if type(ev) is not dict or type(ev.get('op')) is not str:bad()
            op=ev['op']
            if op=='configure':
                keys(ev,'op mode capacity demand paths');mode(ev['mode'])
                for field,size in [('capacity',len(edges)),('demand',len(coms))]:
                    sequence(ev[field],0,size);used=set()
                    for pair in ev[field]:
                        sequence(pair,2,2);i,x=pair;integer(i,0,size-1);integer(x,0,1000)
                        if i in used:bad()
                        used.add(i)
                sequence(ev['paths'],0,96);used=set()
                for change in ev['paths']:
                    sequence(change,3,3);k,p,path=change
                    integer(k,0,len(coms)-1);integer(p,0,len(slots[k])-1)
                    if (k,p) in used:bad()
                    used.add((k,p));path_ok(path,coms[k]['source'],coms[k]['sink'],edges);slots[k][p]=path
                for group in slots:distinct(group)
            elif op=='issue':
                keys(ev,'op id worker');integer(ev['id'],0,10**9);integer(ev['worker'],0,len(workers)-1)
                if ev['id'] in tickets:bad()
                tickets.add(ev['id']);issues_total+=1
            elif op=='deliver':
                keys(ev,'op id');integer(ev['id'],0,10**9)
                if ev['id'] not in tickets:bad()
            elif op=='retune':
                keys(ev,'op rho');integer(ev['rho'],1,8)
            elif op=='save':
                keys(ev,'op name');integer(ev['name'],0,10**9)
                if ev['name'] in saves:bad()
                saves[ev['name']]=[list(group) for group in slots]
            elif op=='restore':
                keys(ev,'op name');integer(ev['name'],0,10**9)
                if ev['name'] not in saves:bad()
                slots=[list(group) for group in saves[ev['name']]]
            elif op in ('step','audit'):keys(ev,'op')
            else:bad()
    if events_total>384 or issues_total>48:bad()
    return v
"""Provision the bundled hash-pinned CPU dependency without network or pip."""
import hashlib
from pathlib import Path
import zipfile
WHEEL='numpy-1.26.4-cp311-cp311-manylinux_2_17_x86_64.manylinux2014_x86_64.whl'
SHA256='666dbfb6ec68962c033a450943ded891bed2d54e6755e35e5835d63f4f6931d5'
def prepare():
    here=Path(__file__).resolve().parent;dest=here/'.deps';marker=dest/'.ready'
    if marker.is_file() and marker.read_text()==SHA256:return dest
    if hashlib.sha256((here/'wheelhouse'/WHEEL).read_bytes()).hexdigest()!=SHA256:
        raise RuntimeError('bundled NumPy dependency hash mismatch')
    dest.mkdir(exist_ok=True)
    with zipfile.ZipFile(here/'wheelhouse'/WHEEL) as archive:archive.extractall(dest)
    marker.write_text(SHA256)
    return dest
if __name__=='__main__':print(prepare())
